// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.audioimport java.util.ArrayDeque/** * NOUS — Circular audio buffer for wake-word pre-roll capture. * * Wake-word detection always lags — by the time the model confirms "Hey NOUS", * the user has already moved on to their actual command. To avoid losing the * audio between wake-word start and detection confirmation, NOUS keeps a * rolling pre-roll buffer of the last N seconds of audio. * * ## Memory Layout * * Samples are stored as a [ShortArray] managed inside an [ArrayDeque] of * fixed-size chunks. Each chunk is one 20 ms frame (320 samples at 16 kHz), * which is the universal processing frame size. This avoids the cost of * shifting a giant contiguous array on every write. * * Memory cost: *   - 2 seconds @ 16 kHz, 16-bit mono = 64 KB *   - 100 chunks × 640 bytes = 64 KB (negligible) * * ## Privacy * *   - Buffer is in-process only — never persisted to disk *   - On [clear], all references are dropped for GC *   - Buffer size is bounded — can't grow unbounded if mic is left on *   - When Privacy Mode is active, buffer is cleared and not refilled * * ## Thread Safety * * All operations are synchronized on the buffer instance. This is safe for * single-producer (mic capture thread) + single-consumer (wake-word detector) * patterns, which is how AudioCapturePipeline uses it. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§4 Wake Word Detection</a> */class CircularAudioBuffer(    /** Audio format of chunks stored in this buffer. */    val format: AudioFormat = AudioFormat.VOICE_16K,    /** Total buffer duration in milliseconds. Default: 2000 (2 seconds). */    private val bufferDurationMs: Int = DEFAULT_BUFFER_DURATION_MS,) {    /** Maximum number of chunks the buffer can hold. */    private val maxChunks: Int = (bufferDurationMs / format.frameDurationMs).coerceAtLeast(1)    /** Deque of audio chunks (oldest at head, newest at tail). */    private val chunks: ArrayDeque<AudioChunk> = ArrayDeque(maxChunks)    /** Monotonic sequence counter for chunks added to this buffer. */    private var nextSequence: Long = 0L    /** Current number of chunks in the buffer. */    val size: Int get() = synchronized(this) { chunks.size }    /** Whether the buffer is at capacity (oldest chunk will be evicted on next write). */    val isFull: Boolean get() = synchronized(this) { chunks.size >= maxChunks }    /** Total duration of audio currently in the buffer (in milliseconds). */    val currentDurationMs: Long        get() = synchronized(this) {            chunks.size.toLong() * format.frameDurationMs        }    /**     * Append a chunk to the buffer.     *     * If the buffer is full, the oldest chunk is evicted (FIFO). The chunk's     * sequence number is assigned by the buffer (caller's sequenceNumber is     * ignored) to ensure monotonic ordering.     *     * @return the evicted chunk (oldest), or null if buffer wasn't full.     *         Callers can use this to detect buffer overflow for diagnostics.     */    fun append(chunk: AudioChunk): AudioChunk? = synchronized(this) {        require(chunk.format == format) {            "Chunk format ${chunk.format} doesn't match buffer format $format"        }        require(chunk.sampleCount == format.samplesPerFrame) {            "Chunk size ${chunk.sampleCount} doesn't match frame size ${format.samplesPerFrame}"        }        val sequenced = chunk.copy(sequenceNumber = nextSequence++)        var evicted: AudioChunk? = null        if (chunks.size >= maxChunks) {            evicted = chunks.pollFirst()        }        chunks.addLast(sequenced)        return evicted    }    /**     * Snapshot the entire buffer contents as a single concatenated chunk.     *     * The returned chunk's samples are a fresh [ShortArray] — modifications     * do not affect the buffer. The timestamp is the oldest chunk's timestamp.     *     * @return concatenated samples, or empty chunk if buffer is empty.     */    fun snapshot(): AudioChunk = synchronized(this) {        if (chunks.isEmpty()) {            return AudioChunk(format, ShortArray(0), 0L)        }        val totalSamples = chunks.size * format.samplesPerFrame        val combined = ShortArray(totalSamples)        var offset = 0        var oldestTs = Long.MAX_VALUE        var oldestSeq = Long.MAX_VALUE        for (chunk in chunks) {            System.arraycopy(chunk.samples, 0, combined, offset, chunk.sampleCount)            offset += chunk.sampleCount            if (chunk.timestampMs < oldestTs) oldestTs = chunk.timestampMs            if (chunk.sequenceNumber < oldestSeq) oldestSeq = chunk.sequenceNumber        }        AudioChunk(            format = format,            samples = combined,            timestampMs = if (oldestTs == Long.MAX_VALUE) 0L else oldestTs,            sequenceNumber = if (oldestSeq == Long.MAX_VALUE) 0L else oldestSeq,        )    }    /**     * Snapshot the last [durationMs] milliseconds of audio.     *     * Useful for getting the recent audio context around a wake-word detection.     *     * @param durationMs how much recent audio to include. If greater than     *                   [currentDurationMs], returns everything available.     */    fun snapshotLast(durationMs: Int): AudioChunk = synchronized(this) {        val chunksNeeded = (durationMs / format.frameDurationMs).coerceAtLeast(1)        val actualChunks = minOf(chunksNeeded, chunks.size)        if (actualChunks == 0) {            return AudioChunk(format, ShortArray(0), 0L)        }        val startIdx = chunks.size - actualChunks        val iter = chunks.iterator()        for (i in 0 until startIdx) iter.next() // skip old chunks        val totalSamples = actualChunks * format.samplesPerFrame        val combined = ShortArray(totalSamples)        var offset = 0        var oldestTs = Long.MAX_VALUE        var oldestSeq = Long.MAX_VALUE        for (i in 0 until actualChunks) {            val chunk = iter.next()            System.arraycopy(chunk.samples, 0, combined, offset, chunk.sampleCount)            offset += chunk.sampleCount            if (chunk.timestampMs < oldestTs) oldestTs = chunk.timestampMs            if (chunk.sequenceNumber < oldestSeq) oldestSeq = chunk.sequenceNumber        }        AudioChunk(            format = format,            samples = combined,            timestampMs = if (oldestTs == Long.MAX_VALUE) 0L else oldestTs,            sequenceNumber = if (oldestSeq == Long.MAX_VALUE) 0L else oldestSeq,        )    }    /**     * Get the most recent chunk (without removing it).     *     * @return the newest chunk, or null if buffer is empty.     */    fun peekNewest(): AudioChunk? = synchronized(this) {        chunks.peekLast()    }    /**     * Get the oldest chunk (without removing it).     *     * @return the oldest chunk, or null if buffer is empty.     */    fun peekOldest(): AudioChunk? = synchronized(this) {        chunks.peekFirst()    }    /**     * Clear the buffer entirely. All chunks are dereferenced for GC.     *     * Called when:     *   - Privacy Mode is enabled (mic disabled)     *   - Wake word is detected (start fresh for next session)     *   - User explicitly clears audio history     */    fun clear() = synchronized(this) {        chunks.clear()    }    companion object {        /** Default buffer duration: 2 seconds (covers wake word + brief pre-roll). */        const val DEFAULT_BUFFER_DURATION_MS = 2_000    }}  // HIGH FIX: Access must be synchronized

